// ==UserScript==
// @name [BOWUDEV] SteamCommunity
// @description [WORKSHOP] Subscribe to all on page. Or all in browsing list.
// @description [WORKSHOP] Download time estimator for workshop files.
// @match https://steamcommunity.com/workshop/browse/
// @match https://steamcommunity.com/sharedfiles/filedetails/
// @grant GM_registerMenuCommand
// @grant GM_unregisterMenuCommand
// @grant GM_notification
// @grant GM_setValue
// @grant GM_getValue
// @version 2025.1.21.16
// @namespace https://github.com/BowuDev/UserCatScriptsPublic
// @homepageURL https://github.com/BowuDev/UserCatScriptsPublic
// @downloadURL https://github.com/BowuDev/UserCatScriptsPublic/raw/refs/heads/main/build/steam.user.js
// @updateURL https://github.com/BowuDev/UserCatScriptsPublic/raw/refs/heads/main/build/steam.user.js
// @supportURL https://github.com/BowuDev/UserCatScriptsPublic/issues
// ==/UserScript==

/* ==UserConfig==
Workshop:
  DownloadEstimator:
    title: "Estimate download time"
    description: "Calculate download time based on average download speed"
    type: "checkbox"
    default: true
  DownloadAvgSpeed:
    title: "Average download speed"
    description: "For example 10MB"
    type: "text"
    default: "50MB"
 ==/UserConfig== */

